def choose_move(observation):
    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def to_xy(p, default=None):
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            return p[0], p[1]
        return default

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    self_pos = to_xy(observation.get("self_position"), (0, 0))
    opp_pos = to_xy(observation.get("opponent_position"), self_pos)

    grid_w = observation.get("grid_width", 0) or 0
    grid_h = observation.get("grid_height", 0) or 0
    max_x = grid_w - 1 if grid_w > 0 else 0
    max_y = grid_h - 1 if grid_h > 0 else 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = ((0, 0), (0, max_y), (max_x, 0), (max_x, max_y))
        target = corners[0]
        best_score = -10**9
        for c in corners:
            score = manhattan(c, opp_pos)
            if score > best_score:
                best_score = score
                target = c
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        best = None
        best_score = None
        for cell in targets:
            c = to_xy(cell)
            if c is None:
                continue
            score = manhattan(self_pos, c) * 2 - manhattan(opp_pos, c)
            if best is None or score < best_score:
                best = c
                best_score = score
        if best is not None:
            return step_toward(self_pos, best)
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = None
    for res in resources:
        r = to_xy(res)
        if r is None:
            continue
        score = manhattan(self_pos, r) - manhattan(opp_pos, r) * 0.5
        if best is None or score < best_score:
            best = r
            best_score = score
    if best is not None:
        return step_toward(self_pos, best)

    return step_toward(self_pos, opp_pos)

